Method.Source:
    /// <summary>
    /// Added by kavya on 11/5/2022 for MPJ_19962_MDRPOTransactionalMissingFields - part 2
    /// Map data fields to virtual fields
    /// </summary>
    public void postLoad()
    {
        MetItemSiteSettingsSetup    ItemSiteSettingsSetup;

        select firstonly TempRcvLimit from ItemSiteSettingsSetup
                where ((ItemSiteSettingsSetup.ItemId == this.ItemNumber && ItemSiteSettingsSetup.InventSiteId == this.ReceivingSiteId)
                 || ItemSiteSettingsSetup.ItemId == this.ItemNumber)
            && ItemSiteSettingsSetup.TempRcvLimit != 0;

        this.METPOLineTempRcvLimit = ItemSiteSettingsSetup.TempRcvLimit? ItemSiteSettingsSetup.TempRcvLimit: InventTable::find(this.ItemNumber).PdsBestBefore;

        next postload();
    }
